function bolt_audit_mark CREATE OR REPLACE FUNCTION public.bolt_audit_mark()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare context jsonb; old_row jsonb; new_row jsonb; key text; marked boolean; direct_row boolean;
begin
	context := bolt_write_context();
	if context is not null then
		old_row := case when TG_OP='INSERT' then null else to_jsonb(OLD) end;
		new_row := case when TG_OP='DELETE' then null else to_jsonb(NEW) end;
		key := TG_TABLE_NAME || '/' || coalesce(new_row->>'id', old_row->>'id');
		select target.erased,target.direct into marked,direct_row from pg_temp.bolt_write_targets target
		where target.token=context->>'token' and target.record_key=key;
		marked := coalesce(marked,false);
		if not marked and not coalesce(direct_row,false) then
			select exists (
				select 1 from (values (old_row), (new_row)) image(j)
				cross join jsonb_array_elements(TG_ARGV[1]::jsonb) edge
				join pg_temp.bolt_erased parent on parent.token=context->>'token'
					and parent.c=edge->>1 and parent.id=image.j->>(edge->>0)
			) into marked;
		end if;
		if marked then
			insert into pg_temp.bolt_erased(token,c,id)
			values(context->>'token',TG_TABLE_NAME,coalesce(new_row->>'id',old_row->>'id'))
			on conflict do nothing;
		end if;
	end if;
	if TG_OP='DELETE' then return OLD; else return NEW; end if;
end;
$function$

function bolt_write_context CREATE OR REPLACE FUNCTION public.bolt_write_context()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare value jsonb;
begin
	value := nullif(current_setting('bolt.write', true), '')::jsonb;
	if value is null then return null; end if;
	if jsonb_typeof(value) is distinct from 'object'
		or jsonb_typeof(value->'token') is distinct from 'string' then
		raise exception using errcode='22023', message='invalid native write context';
	end if;
	if to_regclass('pg_temp.bolt_write_context') is null
		or to_regclass('pg_temp.bolt_write_targets') is null then return null; end if;
	select saved.context into value from pg_temp.bolt_write_context saved where saved.token=value->>'token';
	if not found then return null; end if;
	if jsonb_typeof(value) is distinct from 'object'
		or jsonb_typeof(value->'token') is distinct from 'string'
		or jsonb_typeof(value->'now') is distinct from 'string'
		or jsonb_typeof(value->'actor') is distinct from 'string'
		or coalesce(value->>'mode', '') not in ('write', 'seed', 'restore') then
		raise exception using errcode='22023', message='invalid native write context';
	end if;
	return value;
end;
$function$

function store_anonymise_fields CREATE OR REPLACE FUNCTION public.store_anonymise_fields(table_name text, record_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare context jsonb; key text; fields jsonb;
begin
	context := bolt_write_context();
	key := table_name || '/' || record_id;
	if context is null or context->>'mode' <> 'write'
		or to_regclass('pg_temp.bolt_erased') is null then return '[]'::jsonb; end if;
	select target.anonymise into fields from pg_temp.bolt_write_targets target
	where target.token=context->>'token' and target.record_key=key and target.direct and target.erased
		and exists (select 1 from pg_temp.bolt_erased erased
			where erased.token=target.token and erased.c=table_name and erased.id=record_id);
	if jsonb_typeof(fields) is distinct from 'array' then return '[]'::jsonb; end if;
	return fields;
end;
$function$

function bolt_history_matches CREATE OR REPLACE FUNCTION public.bolt_history_matches(history_model text, metadata jsonb, model_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$ begin
	return case when coalesce(metadata->>'schema','')='' then history_model=model_name else exists(
		select 1 from bolt_history_schema old join bolt_history_current c on c.model=model_name
		join bolt_history_schema current on current.id=c.schema and current.lineage=old.lineage
		where old.id::text=metadata->>'schema') end;
end $function$

function bolt_history_register CREATE OR REPLACE FUNCTION public.bolt_history_register(model_name text, definition jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare held record; version_id uuid; lineage_id uuid; identities jsonb := '{}';
	field_name text; field_spec jsonb; old_name text; identity_id text; prior_fields jsonb;
begin
	select s.* into held from bolt_history_current c join bolt_history_schema s on s.id=c.schema
	where (c.model=model_name and c.active) or (c.model=bolt_history_register.definition->>'was' and c.model<>model_name)
	order by (c.model=model_name) desc limit 1 for update of c;
	if held.id is not null and held.model=model_name and held.definition=bolt_history_register.definition then
		version_id := held.id;
	else
		if to_regclass('bolt_audit_erase') is not null then
			if exists(select 1 from bolt_audit_erase where collection in (model_name,held.model)) then
				raise exception 'History schema change waits for pending erasure of %', model_name;
			end if;
		end if;
		if held.id is not null and to_regclass('bolt_approvals') is not null then
			if exists(select 1 from bolt_approvals a cross join lateral jsonb_array_elements(a.records) r
				where a.state in ('Pending','ChangesRequested') and r->>'collection'=held.model) then
				raise exception 'History schema change waits for open approvals of %', held.model;
			end if;
		end if;
		lineage_id := coalesce(held.lineage,gen_random_uuid());
		prior_fields := coalesce(held.definition->'fields','{}'::jsonb) || coalesce(held.definition->'computed','{}'::jsonb);
		for field_name,field_spec in select key,value from jsonb_each(
			coalesce(bolt_history_register.definition->'fields','{}'::jsonb) || coalesce(bolt_history_register.definition->'computed','{}'::jsonb)) loop
			old_name := case when prior_fields ? field_name then field_name else coalesce(field_spec->>'was',field_name) end;
			identity_id := case when prior_fields ? old_name then held.fields->>old_name end;
			identities := identities || jsonb_build_object(field_name,coalesce(identity_id,gen_random_uuid()::text));
		end loop;
		insert into bolt_history_schema(lineage,model,definition,fields)
		values(lineage_id,model_name,bolt_history_register.definition,identities) returning id into version_id;
		if held.id is not null and held.model<>model_name then
			update bolt_history_current set active=false where model=held.model;
		end if;
		insert into bolt_history_current(model,schema,active) values(model_name,version_id,true)
		on conflict(model) do update set schema=excluded.schema,active=true;
	end if;
	-- Legacy payloads have no historical definition to recover; retain that fact instead of inventing one.
	if to_regclass('bolt_history') is not null then
		update bolt_history set meta=meta || jsonb_build_object('schema',version_id::text,'legacy',true)
		where collection=model_name and coalesce(meta->>'schema','')='';
	end if;
	return version_id;
end $function$
